import { MakeLogicType, connect, kea, listeners, path } from 'kea'

import { projectTreeLogic } from '../../ProjectTree/projectTreeLogic'

export const FILES_TREE_KEY = 'navbar-files'
export const FILES_STARRED_TREE_KEY = 'navbar-files-starred'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface navFilesTabLogicValues {
    searchTerm: string // projectTreeLogic
}

export type navFilesTabLogicType = MakeLogicType<navFilesTabLogicValues, {}>

export const navFilesTabLogic = kea<navFilesTabLogicType>([
    path(['layout', 'panel-layout', 'navbar', 'tabs', 'navFilesTabLogic']),
    connect(() => ({
        values: [projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }), ['searchTerm']],
        logic: [projectTreeLogic({ key: FILES_STARRED_TREE_KEY, root: 'shortcuts://', shortcutScope: 'files' })],
    })),
    listeners(() => ({
        [projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }).actionTypes.setSearchTerm]: ({
            searchTerm,
        }: {
            searchTerm: string
        }) => {
            projectTreeLogic({
                key: FILES_STARRED_TREE_KEY,
                root: 'shortcuts://',
                shortcutScope: 'files',
            }).actions.setSearchTerm(searchTerm)
        },
        [projectTreeLogic({ key: FILES_TREE_KEY, root: 'project://' }).actionTypes.clearSearch]: () => {
            projectTreeLogic({
                key: FILES_STARRED_TREE_KEY,
                root: 'shortcuts://',
                shortcutScope: 'files',
            }).actions.clearSearch()
        },
    })),
])
